    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;cole-Universelle-(&#201;cole).html&quot; title=&quot;L&amp;#39;&#233;cole Universelle&quot;&gt;&#201;cole universelle&lt;/a&gt;&lt;/li&gt;
